"use client";

import Link from "next/link";
import { useRouter } from "next/navigation";
import { useCallback, useEffect, useRef, useState } from "react";
import { Activity as ActivityIcon, Archive, ArrowLeft, ArrowRight, Bell, Check, CheckCheck, ChevronDown, ChevronRight, CircleHelp, Clock3, Copy, Ellipsis, FileImage, FolderClosed, Grid2X2, HardDrive, LayoutGrid, Link2, List, LogOut, Menu, MessageCircle, Plus, Search, Settings2, Share2, SlidersHorizontal, Sparkles, Upload, Users } from "lucide-react";
import { Avatar, Button, Field, IconButton, Logo, Modal, Select, ThemeToggle, ToastProvider, inputClass, useToast } from "./ui";
import { ReviewPanel, type NewComment } from "./review-panel";
import { api, imageDimensions, uploadToS3 } from "@/lib/client-api";
import { createDemoData } from "@/lib/demo";
import { decisionLabel, formatBytes, latestVersion, projectDecision, readableDate, relativeTime } from "@/lib/format";
import type { Asset, AssetVersion, Comment, Decision, Project, WorkspaceData } from "@/lib/types";

type View = "projects" | "review" | "approved" | "activity" | "settings";
export function WorkspaceApp({ initialData, demo = false }: { initialData: WorkspaceData; demo?: boolean }) {
  return <ToastProvider><Workspace initialData={initialData} demo={demo}/></ToastProvider>;
}

function Workspace({ initialData, demo }: { initialData: WorkspaceData; demo: boolean }) {
  const [data, setData] = useState(initialData);
  const [view, setView] = useState<View>("projects");
  const [projectId, setProjectId] = useState<string | null>(null);
  const [reviewId, setReviewId] = useState<string | null>(null);
  const [tab, setTab] = useState("active");
  const [search, setSearch] = useState("");
  const [sort, setSort] = useState("recent");
  const [listView, setListView] = useState(false);
  const [mobileMenu, setMobileMenu] = useState(false);
  const [command, setCommand] = useState(false);
  const [create, setCreate] = useState(false);
  const [editProject, setEditProject] = useState<Project | null>(null);
  const [shareProject, setShareProject] = useState<Project | null>(null);
  const [upload, setUpload] = useState<{ projectId: string; assetId?: string } | null>(null);
  const [help, setHelp] = useState(false);
  const [hydrated, setHydrated] = useState(false);
  const toast = useToast();
  const router = useRouter();
  const blobUrls = useRef<string[]>([]);
  const canEdit = data.workspace.role !== "viewer";
  const activeProject = data.projects.find(p => p.id === projectId);
  const reviewAsset = data.assets.find(a => a.id === reviewId);
  const reviewProject = data.projects.find(p => p.id === reviewAsset?.projectId);
  const closeReview = useCallback(() => setReviewId(null), []);

  useEffect(() => {
    if (demo) {
      try {
        const saved = localStorage.getItem("proofly-demo-v1");
        if (saved) { const parsed = JSON.parse(saved); if (parsed.workspace?.id === "demo-workspace" && Array.isArray(parsed.projects) && Array.isArray(parsed.assets) && Array.isArray(parsed.comments)) setData(parsed); }
      } catch { /* Start with the supplied sample workspace when browser storage is unavailable. */ }
      const id = new URLSearchParams(window.location.search).get("project"); if (id) setProjectId(id);
    }
    setHydrated(true);
  }, [demo]);
  useEffect(() => {
    if (!demo || !hydrated) return;
    try {
      const assets = data.assets.map(a => ({ ...a, versions: a.versions.filter(v => v.previewUrl.startsWith("/artwork/")) })).filter(a => a.versions.length);
      const versionIds = new Set(assets.flatMap(a => a.versions.map(v => v.id)));
      localStorage.setItem("proofly-demo-v1", JSON.stringify({ ...data, assets, comments: data.comments.filter(c => versionIds.has(c.versionId)) }));
    } catch { /* The demo remains usable when storage is full or disabled. */ }
  }, [data, demo, hydrated]);
  useEffect(() => () => { blobUrls.current.forEach(url => URL.revokeObjectURL(url)); }, []);
  useEffect(() => {
    const handler = (e: KeyboardEvent) => { if ((e.metaKey || e.ctrlKey) && e.key.toLowerCase() === "k") { e.preventDefault(); setCommand(v => !v); } };
    document.addEventListener("keydown", handler); return () => document.removeEventListener("keydown", handler);
  }, []);

  async function refresh() { setData(await api<WorkspaceData>("/workspace")); }
  function activity(title: string, detail: string) { return { id: crypto.randomUUID(), title, detail, createdAt: new Date().toISOString() }; }
  async function saveProject(values: { name: string; client: string; description: string; color: string; dueDate: string | null }) {
    if (demo) {
      const project: Project = { ...values, id: crypto.randomUUID(), archived: false, createdAt: new Date().toISOString() };
      setData(d => ({ ...d, projects: [project, ...d.projects], activity: [activity("You created a project", project.name), ...d.activity] })); setProjectId(project.id);
    } else { const project = await api<Project>("/projects", { method: "POST", body: JSON.stringify(values) }); await refresh(); setProjectId(project.id); }
    setCreate(false); setView("projects"); toast("A fresh start. Your project is ready.");
  }
  async function updateProject(project: Project, values: Partial<Project>) {
    if (demo) setData(d => ({ ...d, projects: d.projects.map(p => p.id === project.id ? { ...p, ...values } : p) }));
    else { await api(`/projects/${project.id}`, { method: "PATCH", body: JSON.stringify(values) }); await refresh(); }
    setEditProject(null); toast(values.archived === undefined ? "Project details updated." : values.archived ? "Project archived." : "Project restored.");
  }
  async function addComment(versionId: string, values: NewComment) {
    if (demo) { const comment: Comment = { id: crypto.randomUUID(), versionId, authorId: data.user.id, authorName: data.user.name, body: values.body, x: values.x, y: values.y, parentId: values.parentId ?? null, resolved: false, createdAt: new Date().toISOString() }; setData(d => ({ ...d, comments: [...d.comments, comment], activity: [activity("You left feedback", values.body.slice(0, 90)), ...d.activity] })); }
    else { const comment = await api<Comment>(`/versions/${versionId}/comments`, { method: "POST", body: JSON.stringify(values) }); setData(d => ({ ...d, comments: [...d.comments, comment] })); }
  }
  async function resolveComment(id: string, resolved: boolean) {
    if (!demo) await api(`/comments/${id}`, { method: "PATCH", body: JSON.stringify({ resolved }) });
    setData(d => ({ ...d, comments: d.comments.map(c => c.id === id ? { ...c, resolved } : c) }));
  }
  async function decide(id: string, decision: Decision) {
    if (!demo) await api(`/versions/${id}`, { method: "PATCH", body: JSON.stringify({ decision }) });
    setData(d => ({ ...d, assets: d.assets.map(a => ({ ...a, versions: a.versions.map(v => v.id === id ? { ...v, decision } : v) })), activity: [activity(decision === "approved" ? "A version was approved" : "Changes were requested", reviewProject?.name ?? "Creative review"), ...d.activity] }));
  }
  async function uploadFile(file: File, onProgress: (n: number) => void, signal: AbortSignal) {
    if (!upload) return;
    const dimensions = await imageDimensions(file);
    if (dimensions.width > 20000 || dimensions.height > 20000) throw new Error("Images must be no larger than 20,000 pixels on either side.");
    if (demo) {
      if (signal.aborted) throw new Error("Upload cancelled.");
      const url = URL.createObjectURL(file); blobUrls.current.push(url);
      const asset = data.assets.find(a => a.id === upload.assetId);
      const version: AssetVersion = { id: crypto.randomUUID(), number: asset ? latestVersion(asset).number + 1 : 1, previewUrl: url, ...dimensions, byteSize: file.size, contentType: file.type, createdAt: new Date().toISOString(), decision: "in_review" };
      setData(d => ({ ...d, assets: asset ? d.assets.map(a => a.id === asset.id ? { ...a, versions: [...a.versions, version] } : a) : [...d.assets, { id: crypto.randomUUID(), projectId: upload.projectId, name: file.name.replace(/\.[^.]+$/, ""), versions: [version] }], activity: [activity("You uploaded a design", file.name), ...d.activity] })); onProgress(100);
    } else {
      const signed = await api<{ id: string; url: string; fields: Record<string, string> }>("/uploads", { method: "POST", body: JSON.stringify({ projectId: upload.projectId, assetId: upload.assetId, filename: file.name, contentType: file.type, byteSize: file.size, ...dimensions }), signal });
      await uploadToS3(file, signed.url, signed.fields, onProgress, signal);
      await api(`/uploads/${signed.id}/complete`, { method: "POST", body: "{}", signal }); onProgress(100); await refresh();
    }
    setUpload(null); toast(demo ? "Design added. Demo uploads stay in this tab." : "Your design is ready for review.");
  }
  function navigate(v: View) { setView(v); setProjectId(null); setMobileMenu(false); setSearch(""); }
  const active = data.projects.filter(p => !p.archived);
  const counts = { review: active.filter(p => ["in_review", "changes_requested"].includes(projectDecision(p, data.assets))).length, approved: active.filter(p => projectDecision(p, data.assets) === "approved").length };
  const projects = data.projects.filter(p => {
    if (view === "review" && (p.archived || !["in_review", "changes_requested"].includes(projectDecision(p, data.assets)))) return false;
    if (view === "approved" && (p.archived || projectDecision(p, data.assets) !== "approved")) return false;
    if (view === "projects" && (tab === "archived" ? !p.archived : p.archived)) return false;
    return `${p.name} ${p.client} ${p.description}`.toLowerCase().includes(search.toLowerCase());
  }).sort((a, b) => sort === "name" ? a.name.localeCompare(b.name) : sort === "due" ? (a.dueDate ?? "9999").localeCompare(b.dueDate ?? "9999") : b.createdAt.localeCompare(a.createdAt));
  const usedBytes = data.assets.reduce((sum, a) => sum + a.versions.reduce((n, v) => n + v.byteSize, 0), 0);

  return <div className="min-h-dvh bg-paper">
    {mobileMenu && <button aria-label="Close navigation" className="fixed inset-0 z-30 bg-black/30 lg:hidden" onClick={() => setMobileMenu(false)}/>}
    <aside className={`fixed inset-y-0 left-0 z-30 flex w-[230px] flex-col border-r border-line bg-surface transition-transform lg:translate-x-0 ${mobileMenu ? "translate-x-0" : "-translate-x-full"}`}>
      <div className="flex h-21 items-center px-6"><Logo/></div>
      <button onClick={() => navigate("settings")} className="mx-4 mb-6 flex items-center gap-2.5 rounded-xl border border-line p-2.5 text-left transition hover:bg-subtle"><span className="flex size-8 shrink-0 items-center justify-center rounded-lg bg-accent-soft text-sm font-semibold text-accent">{data.workspace.name[0]}</span><span className="min-w-0 flex-1"><span className="block truncate text-[12px] font-semibold">{data.workspace.name}</span><span className="mt-0.5 block text-[10px] text-muted">Creative workspace</span></span><ChevronDown className="size-3 text-muted"/></button>
      <button onClick={() => { setCommand(true); setMobileMenu(false); }} className="mx-4 mb-7 flex items-center gap-2.5 rounded-lg bg-paper px-3 py-2.5 text-[12px] text-muted"><Search className="size-3.5"/>Quick search<span className="ml-auto rounded border border-line px-1 py-0.5 text-[9px]">⌘ K</span></button>
      <p className="mb-3 px-6 text-[9px] font-medium tracking-[.14em] text-muted uppercase">Workspace</p>
      <nav className="space-y-1 px-3" aria-label="Workspace navigation">
        {([{ id: "projects", label: "Projects", icon: LayoutGrid }, { id: "review", label: "For review", icon: MessageCircle, count: counts.review }, { id: "approved", label: "Approved", icon: CheckCheck, count: counts.approved }, { id: "activity", label: "Activity", icon: ActivityIcon }] as const).map(item => <button key={item.id} onClick={() => navigate(item.id)} aria-current={view === item.id ? "page" : undefined} className={`flex w-full items-center gap-3 rounded-lg px-3 py-2.5 text-[12px] transition ${view === item.id ? "bg-accent-soft font-semibold text-accent" : "text-muted hover:bg-subtle hover:text-ink"}`}><item.icon className="size-4"/>{item.label}{"count" in item && <span className={`ml-auto rounded px-1.5 py-0.5 text-[10px] ${view === item.id ? "bg-accent/10" : "bg-subtle"}`}>{item.count}</span>}</button>)}
      </nav>
      <div className="mx-6 my-6 border-t border-line"/>
      <div className="flex items-center justify-between px-6"><p className="text-[9px] font-medium tracking-[.14em] text-muted uppercase">Recent projects</p>{canEdit && <button title="Create a project" aria-label="Create a project" onClick={() => setCreate(true)} className="text-muted hover:text-accent"><Plus className="size-3.5"/></button>}</div>
      <div className="scrollbar-thin mt-3 max-h-48 space-y-0.5 overflow-y-auto px-4">{active.slice(0, 5).map(p => <button key={p.id} onClick={() => { setProjectId(p.id); setView("projects"); setMobileMenu(false); }} className={`flex w-full items-center gap-2.5 rounded-lg px-2 py-2 text-left text-[11px] hover:bg-subtle ${projectId === p.id ? "text-ink" : "text-muted"}`}><span className="size-2 shrink-0 rounded-sm" style={{ background: p.color }}/><span className="truncate">{p.client || p.name}</span></button>)}{!active.length && <p className="px-2 py-2 text-[11px] text-muted">Your next project starts here.</p>}</div>
      <div className="mt-auto px-4 pt-6 pb-4">
        {demo && <div className="mb-4 rounded-xl border border-line bg-paper p-3.5"><span className="mb-2 inline-flex items-center gap-1.5 text-[11px] font-semibold"><Sparkles className="size-3.5 text-accent"/>A little look around</span><p className="text-[10px] leading-relaxed text-muted">You’re in the demo. Make yourself at home, then create your own space.</p><Link href="/register" className="mt-3 flex items-center justify-between text-[11px] font-semibold text-accent">Make it yours<ArrowRight className="size-3.5"/></Link></div>}
        <button onClick={() => navigate("settings")} className="flex w-full items-center gap-3 rounded-lg px-2 py-2 text-[12px] text-muted hover:bg-subtle"><Settings2 className="size-4"/>Settings</button><button onClick={() => setHelp(true)} className="flex w-full items-center gap-3 rounded-lg px-2 py-2 text-[12px] text-muted hover:bg-subtle"><CircleHelp className="size-4"/>A helping hand</button>
        <div className="mt-4 flex items-center gap-2.5 border-t border-line pt-4"><Avatar name={data.user.name}/><div className="min-w-0 flex-1"><p className="truncate text-[11px] font-semibold">{data.user.name}</p><p className="mt-0.5 text-[9px] text-muted">{demo ? "Demo workspace" : data.workspace.role === "owner" ? "Workspace owner" : "Team member"}</p></div>{demo ? <Link href="/login" aria-label="Sign in" className="rounded-lg p-2 text-muted hover:bg-subtle"><LogOut className="size-3.5"/></Link> : <IconButton label="Sign out" onClick={async () => { try { await api("/auth/logout", { method: "POST", body: "{}" }); router.push("/"); router.refresh(); } catch (e) { toast((e as Error).message, true); } }}><LogOut className="size-3.5"/></IconButton>}</div>
      </div>
    </aside>

    <div className="lg:pl-[230px]">
      <header className="flex h-17 items-center gap-2 border-b border-line bg-surface px-5 sm:px-8"><IconButton label="Open navigation" className="lg:hidden" onClick={() => setMobileMenu(true)}><Menu className="size-5"/></IconButton><FolderClosed className="mr-1 hidden size-3.5 text-muted sm:block"/><span className="text-[11px] text-muted">Workspace</span><ChevronRight className="mx-1 size-3 text-muted/60"/><span className="truncate text-[11px] font-medium">{activeProject?.client || ({ projects: "Projects", review: "For review", approved: "Approved", activity: "Activity", settings: "Settings" })[view]}</span><div className="ml-auto flex items-center gap-2"><ThemeToggle/><IconButton label="Recent activity" onClick={() => navigate("activity")}><Bell className="size-4"/></IconButton><span className="mx-1 h-5 w-px bg-line"/><div className="hidden items-center -space-x-1.5 sm:flex">{data.members.slice(0, 3).map((m, i) => <Avatar key={m.id} name={m.name} size="sm" color={i}/>)}</div><IconButton label="Manage team" onClick={() => navigate("settings")}><Users className="size-4"/></IconButton></div></header>
      <main className="mx-auto max-w-[1550px] px-5 pt-9 pb-12 sm:px-8 xl:px-10">
        {view === "activity" ? <div className="max-w-3xl animate-enter"><Eyebrow>THE LITTLE THINGS ADD UP</Eyebrow><h1 className="mt-2 text-3xl font-medium tracking-[-.045em]">Work in motion.</h1><p className="mt-3 text-sm text-muted">A shared story of feedback, fresh ideas, and things getting done.</p><div className="mt-9 rounded-2xl border border-line bg-surface p-5 sm:p-7">{data.activity.length ? data.activity.map((a, i) => <div key={a.id} className="relative flex gap-4 pb-7 last:pb-0">{i !== data.activity.length - 1 && <span className="absolute top-9 bottom-0 left-[17px] w-px bg-line"/>}<span className="z-1 flex size-9 shrink-0 items-center justify-center rounded-xl border border-line bg-paper"><ActivityIcon className="size-4 text-accent"/></span><div className="pt-1"><p className="text-sm font-medium">{a.title}</p><p className="mt-1 text-xs text-muted">{a.detail}</p><p className="mt-2 text-[10px] text-muted">{relativeTime(a.createdAt)}</p></div></div>) : <EmptyState title="A fresh page" description="Upload a design or leave feedback to start your workspace’s story."/>}</div></div>
        : view === "settings" ? <SettingsPanel data={data} demo={demo} usedBytes={usedBytes} onUpdate={name => setData(d => ({ ...d, workspace: { ...d.workspace, name } }))} onReset={() => { localStorage.removeItem("proofly-demo-v1"); setData(createDemoData()); toast("Demo workspace refreshed."); }}/>
        : activeProject ? <div className="animate-enter"><button onClick={() => setProjectId(null)} className="mb-6 flex items-center gap-2 text-xs text-muted hover:text-accent"><ArrowLeft className="size-3.5"/>All projects</button><div className="flex flex-wrap items-start justify-between gap-5"><div><div className="mb-3 flex items-center gap-2"><span style={{ background: activeProject.color }} className="size-2 rounded-full"/><Eyebrow>{activeProject.client || "CREATIVE PROJECT"}</Eyebrow><Status status={projectDecision(activeProject, data.assets)}/></div><h1 className="text-3xl font-medium tracking-[-.045em]">{activeProject.name}</h1><p className="mt-3 max-w-xl text-sm leading-relaxed text-muted">{activeProject.description || "A space for good ideas and clear feedback."}</p><p className="mt-3 flex items-center gap-2 text-[11px] text-muted"><Clock3 className="size-3.5"/> {activeProject.dueDate ? `Due ${readableDate(activeProject.dueDate)}` : "Space to find the right direction"}</p></div><div className="flex items-center gap-2"><Button variant="secondary" onClick={() => setShareProject(activeProject)}><Share2 className="size-3.5"/>Share review</Button>{canEdit && <><Button onClick={() => setUpload({ projectId: activeProject.id })}><Upload className="size-3.5"/>Upload design</Button><IconButton label="Edit project" onClick={() => setEditProject(activeProject)}><Ellipsis className="size-5"/></IconButton></>}</div></div><div className="mt-9 flex items-center justify-between border-b border-line pb-4"><h2 className="text-sm font-medium">Project files <span className="ml-2 text-xs text-muted">{data.assets.filter(a => a.projectId === activeProject.id).length}</span></h2><span className="text-[11px] text-muted">Every version. Every conversation.</span></div><div className="mt-6 grid gap-5 sm:grid-cols-2 xl:grid-cols-3">{data.assets.filter(a => a.projectId === activeProject.id).map(a => <AssetCard key={a.id} asset={a} comments={data.comments} onOpen={() => setReviewId(a.id)}/>)}{canEdit && <button onClick={() => setUpload({ projectId: activeProject.id })} className="group flex min-h-65 flex-col items-center justify-center gap-3 rounded-2xl border border-dashed border-line bg-surface/50 px-5 py-10 transition hover:border-accent/50 hover:bg-accent-soft/30"><span className="flex size-11 items-center justify-center rounded-xl bg-subtle text-muted transition group-hover:text-accent"><Plus className="size-5"/></span><span className="text-sm font-medium">Room for another idea</span><span className="text-xs text-muted">Upload a PNG, JPG, or WebP</span></button>}{!canEdit && !data.assets.some(a => a.projectId === activeProject.id) && <EmptyState title="No designs yet" description="New designs will appear here when an editor uploads them."/>}</div></div>
        : <div className="animate-enter"><div className="flex flex-wrap items-start justify-between gap-5"><div><Eyebrow>{view === "approved" ? "A MOMENT WORTH CELEBRATING" : view === "review" ? "A FRESH PAIR OF EYES" : "A LITTLE CLARITY. A LOT OF PROGRESS."}</Eyebrow><h1 className="mt-2 text-[30px] leading-tight font-medium tracking-[-.05em] sm:text-[36px]">{view === "approved" ? "Good work, signed off." : view === "review" ? "Your perspective matters." : "Your work, moving forward."}<span className="text-accent">{view === "projects" ? " ✳" : ""}</span></h1><p className="mt-3 text-[12px] leading-relaxed text-muted">{view === "approved" ? "The right version, with everyone on the same page." : view === "review" ? "A few thoughtful words can make all the difference." : "One home for your projects, feedback, and those little ‘nailed it’ moments."}</p></div>{canEdit && <Button onClick={() => setCreate(true)} className="mt-1"><Plus className="size-4"/>New project</Button>}</div>
          {view === "projects" && tab !== "archived" && <div className="mt-8 grid gap-4 md:grid-cols-[1.65fr_1fr]"><div className="relative overflow-hidden rounded-2xl border border-[#e8dfd2] bg-[#f2ece1] px-6 py-6 text-[#423c33] sm:px-7"><span className="relative z-1 mb-4 inline-flex items-center gap-1.5 rounded-full border border-[#ddd3c1] px-2.5 py-1 text-[9px] font-medium"><span className="size-1 rounded-full bg-accent"/>GOOD THINGS TAKE A LITTLE TEAMWORK</span><h2 className="relative z-1 max-w-64 text-[24px] leading-[1.2] font-medium tracking-[-.045em]">Less back-and-forth.<br/>More moving forward.</h2><button onClick={() => navigate("review")} className="relative z-1 mt-6 flex items-center gap-2 text-[11px] font-semibold">Take a look at what’s next <ArrowRight className="size-3.5"/></button><div aria-hidden="true" className="absolute top-12 -right-5 hidden h-37 w-44 rotate-[12deg] rounded-xl border border-[#ded2bc] bg-[#fffcf5] p-3 shadow-[0_6px_25px_#8c735a12] min-[850px]:block xl:right-8"><div className="mb-3 flex gap-1"><span className="size-1.5 rounded-full bg-[#e9b29e]"/><span className="size-1.5 rounded-full bg-[#d8cfbb]"/></div><div className="h-16 rounded-lg bg-[#b7c6aa] px-2.5 pt-3 font-serif text-2xl text-[#526248]">a little<br/><i>perspective.</i></div><div className="mt-3 flex items-center gap-1.5 text-[8px] text-[#7d786b]"><span className="size-3 rounded-full bg-[#e9cbb6]"/>Looking good!<Check className="ml-auto size-3 text-[#728262]"/></div></div></div>
            <div className="rounded-2xl border border-line bg-surface p-6"><div className="mb-5 flex items-center justify-between"><span className="text-[11px] font-medium">A little overview</span><SlidersHorizontal className="size-3.5 text-muted"/></div><div className="grid grid-cols-3 divide-x divide-line"><Stat value={active.length} label="Active projects"/><Stat value={counts.review} label="For review"/><Stat value={counts.approved} label="Approved"/></div><p className="mt-5 flex items-center gap-1.5 border-t border-line pt-4 text-[10px] text-muted"><span className="size-1.5 rounded-full bg-[#94aa84]"/>{counts.review ? `${counts.review} project${counts.review === 1 ? " is" : "s are"} ready for a fresh pair of eyes.` : "A clear space for your next big idea."}</p></div></div>}
          <div className="mt-8 flex flex-wrap items-center justify-between gap-4 border-b border-line"><div className="flex items-center gap-6 self-stretch"><button onClick={() => setTab("active")} className={`relative pb-4 text-[12px] font-medium ${tab === "active" ? "text-ink after:absolute after:inset-x-0 after:bottom-0 after:h-0.5 after:bg-accent" : "text-muted"}`}>{view === "review" ? "Ready for feedback" : view === "approved" ? "Approved projects" : "All projects"}<span className="ml-2 rounded-md bg-subtle px-1.5 py-0.5 text-[10px] text-muted">{view === "projects" ? active.length : projects.length}</span></button>{view === "projects" && <button onClick={() => setTab("archived")} className={`relative pb-4 text-[12px] ${tab === "archived" ? "font-medium text-ink after:absolute after:inset-x-0 after:bottom-0 after:h-0.5 after:bg-accent" : "text-muted"}`}>Archived</button>}</div><div className="mb-3 flex flex-wrap items-center gap-2"><div className="relative"><Search className="absolute top-1/2 left-2.5 size-3.5 -translate-y-1/2 text-muted"/><input aria-label="Search projects" value={search} onChange={e => setSearch(e.target.value)} placeholder="Find a project…" className="h-8 w-35 rounded-lg border border-line bg-surface pr-2 pl-8 text-[11px] outline-none focus:border-accent sm:w-43"/></div><Select aria-label="Sort projects" value={sort} onChange={e => setSort(e.target.value)}><option value="recent">Latest first</option><option value="name">A → Z</option><option value="due">Due date</option></Select><span className="mx-1 h-5 w-px bg-line"/><div className="flex rounded-lg border border-line bg-surface p-0.5"><IconButton label="Grid view" className={`size-7 ${!listView ? "bg-subtle text-ink" : ""}`} onClick={() => setListView(false)}><Grid2X2 className="size-3.5"/></IconButton><IconButton label="List view" className={`size-7 ${listView ? "bg-subtle text-ink" : ""}`} onClick={() => setListView(true)}><List className="size-3.5"/></IconButton></div></div></div>
          {projects.length ? <div className={`mt-6 ${listView ? "space-y-3" : "grid gap-5 sm:grid-cols-2 xl:grid-cols-3"}`}>{projects.map(p => <ProjectCard key={p.id} project={p} assets={data.assets} comments={data.comments} members={data.members} list={listView} onOpen={() => setProjectId(p.id)} onMenu={() => setEditProject(p)} canEdit={canEdit}/>)}</div> : <EmptyState title={search ? "No matches, just yet" : tab === "archived" ? "Nothing tucked away" : view === "approved" ? "Good things are on their way" : "A little room for something great"} description={search ? "Try another project or client name." : tab === "archived" ? "Archived projects stay here whenever you need them." : "Create a project, add a design, and bring your next idea into focus."} action={canEdit && !search && tab !== "archived" ? <Button onClick={() => setCreate(true)}><Plus className="size-4"/>Create a project</Button> : undefined}/>}
          <div className="mt-9 flex items-center justify-between text-[10px] text-muted"><span>{projects.length} project{projects.length !== 1 ? "s" : ""} · A little more organized.</span><span className="hidden items-center gap-1.5 sm:flex"><span className="size-1.5 rounded-full bg-[#94aa84]"/>{demo ? "Demo changes saved in your browser" : "Your team’s shared workspace"}</span></div>
        </div>}
      </main>
    </div>

    {create && <ProjectModal onClose={() => setCreate(false)} onSave={saveProject}/>}
    {editProject && <ProjectModal project={editProject} onClose={() => setEditProject(null)} onSave={values => updateProject(editProject, values)} onArchive={() => updateProject(editProject, { archived: !editProject.archived })}/>}
    {shareProject && <ShareModal project={shareProject} demo={demo} canEdit={canEdit} onClose={() => setShareProject(null)}/>}
    {upload && <UploadModal demo={demo} newVersion={!!upload.assetId} onClose={() => setUpload(null)} onUpload={uploadFile}/>}
    {reviewAsset && reviewProject && <ReviewPanel project={reviewProject} assets={data.assets.filter(a => a.projectId === reviewProject.id)} comments={data.comments} initialAssetId={reviewAsset.id} canEdit={canEdit} onClose={closeReview} onComment={addComment} onResolve={resolveComment} onDecision={decide} onUpload={canEdit ? assetId => setUpload({ projectId: reviewProject.id, assetId }) : undefined}/>}
    {command && <Modal title="Find your next thing" onClose={() => setCommand(false)}><input autoFocus value={search} onChange={e => setSearch(e.target.value)} aria-label="Search workspace" placeholder="Search projects or clients…" className={inputClass}/><div className="mt-4 max-h-70 space-y-1 overflow-y-auto">{data.projects.filter(p => `${p.name} ${p.client}`.toLowerCase().includes(search.toLowerCase())).map(p => <button key={p.id} onClick={() => { setProjectId(p.id); setView("projects"); setCommand(false); setSearch(""); }} className="flex w-full items-center gap-3 rounded-lg px-3 py-3 text-left hover:bg-subtle"><span className="size-2 rounded-sm" style={{ background: p.color }}/><span className="min-w-0 flex-1"><span className="block truncate text-xs font-medium">{p.name}</span><span className="mt-1 block text-[10px] text-muted">{p.client}</span></span><ChevronRight className="size-3.5 text-muted"/></button>)}</div>{canEdit && <Button variant="secondary" className="mt-4 w-full" onClick={() => { setCommand(false); setCreate(true); }}><Plus className="size-4"/>Create a new project</Button>}</Modal>}
    {help && <Modal title="A little clarity goes a long way." subtitle="From the first idea to the final yes, here’s your path." onClose={() => setHelp(false)}><ol className="space-y-5">{[["Make a little space", "Create a project for your client or creative idea."], ["Put your work out there", "Upload a design, then click anywhere on it to pin feedback."], ["Find a fresh perspective", "Upload a new version and use comparison to see what changed."], ["Get everyone on the same page", "Resolve conversations and approve the version that feels right."]].map(([title, text], i) => <li key={title} className="flex gap-3"><span className="flex size-7 shrink-0 items-center justify-center rounded-lg bg-accent-soft text-xs text-accent">{i + 1}</span><div><h3 className="text-sm font-medium">{title}</h3><p className="mt-1 text-xs leading-relaxed text-muted">{text}</p></div></li>)}</ol><Button className="mt-7 w-full" onClick={() => setHelp(false)}>Let’s make something good<ArrowRight className="size-3.5"/></Button></Modal>}
  </div>;
}

function Eyebrow({ children }: { children: React.ReactNode }) { return <p className="text-[9px] font-medium tracking-[.12em] text-muted uppercase">{children}</p>; }
function Stat({ value, label }: { value: number; label: string }) { return <div className="px-3 first:pl-0"><p className="text-[32px] leading-none font-medium tracking-tight">{String(value).padStart(2, "0")}</p><p className="mt-2.5 text-[9px] text-muted">{label}</p></div>; }
function Status({ status }: { status: Decision | "empty" }) { return <span className={`inline-flex shrink-0 items-center gap-1.5 rounded-full px-2 py-1 text-[9px] font-medium ${status === "approved" ? "bg-[#edf3e8] text-[#637c4e] dark:bg-[#2a3827] dark:text-[#a6c293]" : status === "changes_requested" ? "bg-[#fff0e8] text-[#b97748] dark:bg-[#423026] dark:text-[#dfb08d]" : status === "empty" ? "bg-subtle text-muted" : "bg-[#f0edfa] text-[#8c77b5] dark:bg-[#342c46] dark:text-[#beaae0]"}`}><span className="size-1 rounded-full bg-current"/>{decisionLabel[status]}</span>; }
function ProjectCard({ project, assets, comments, members, list, onOpen, onMenu, canEdit }: { project: Project; assets: Asset[]; comments: Comment[]; members: WorkspaceData["members"]; list: boolean; onOpen: () => void; onMenu: () => void; canEdit: boolean }) {
  const files = assets.filter(a => a.projectId === project.id);
  const cover = files[0] ? latestVersion(files[0]) : undefined;
  const versionIds = new Set(files.flatMap(a => a.versions.map(v => v.id)));
  const totalComments = comments.filter(c => versionIds.has(c.versionId) && !c.parentId).length;
  return <article className={`group overflow-hidden rounded-2xl border border-line bg-surface transition duration-200 hover:border-[#d8d4cc] hover:shadow-[0_8px_30px_#28201a08] ${list ? "flex items-center" : ""}`}>
    <button onClick={onOpen} aria-label={`Open project ${project.name}`} className={`relative block shrink-0 overflow-hidden bg-subtle ${list ? "m-2 h-22 w-30 rounded-lg" : "m-2 mb-0 aspect-[1.6] w-[calc(100%-16px)] rounded-xl"}`}>{cover ? <img src={cover.previewUrl} alt={`${project.client} design preview`} className="size-full object-cover transition duration-500 group-hover:scale-[1.035]"/> : <span className="flex size-full items-center justify-center" style={{ background: `${project.color}35` }}><FolderClosed className="size-10 opacity-30"/></span>}{cover && !list && <span className="absolute top-2.5 left-2.5 rounded-md bg-white/80 px-2 py-1 text-[8px] font-medium text-[#484742] backdrop-blur-sm">{files.length} file{files.length !== 1 ? "s" : ""} <span className="mx-1 opacity-40">/</span> v{cover.number}</span>}</button>
    <div className={`min-w-0 flex-1 ${list ? "p-3 sm:px-5" : "px-4 pt-4 pb-3.5"}`}><div className="flex items-start justify-between gap-2"><div className="min-w-0"><p className="mb-1.5 truncate text-[9px] text-muted">{project.client || "Independent project"}</p><button onClick={onOpen} className="block w-full truncate text-left text-[12px] leading-relaxed font-semibold tracking-[-.015em] hover:text-accent">{project.name}</button></div>{canEdit && <IconButton label={`Edit ${project.name}`} className="-mt-1 -mr-1 size-7" onClick={onMenu}><Ellipsis className="size-4"/></IconButton>}</div><div className={`mt-3.5 flex flex-wrap items-center justify-between gap-2 ${list ? "sm:mt-2" : ""}`}><Status status={projectDecision(project, assets)}/><span className="text-[9px] text-muted">{project.dueDate ? `Due ${readableDate(project.dueDate)}` : "At your own pace"}</span></div>{!list && <div className="mt-4 flex items-center justify-between border-t border-line pt-3"><div className="flex -space-x-1.5">{members.slice(0, 2).map((m, i) => <Avatar key={m.id} name={m.name} size="sm" color={i}/>)}</div><button onClick={onOpen} className="flex items-center gap-1.5 text-[10px] text-muted hover:text-accent"><MessageCircle className="size-3"/>{totalComments}<span className="mx-1 text-line">/</span><span>{cover ? relativeTime(cover.createdAt) : "Just getting started"}</span></button></div>}</div>
  </article>;
}
function AssetCard({ asset, comments, onOpen }: { asset: Asset; comments: Comment[]; onOpen: () => void }) {
  const version = latestVersion(asset);
  return <button onClick={onOpen} className="group overflow-hidden rounded-2xl border border-line bg-surface text-left transition hover:border-accent/30"><div className="m-2 aspect-[1.45] overflow-hidden rounded-xl bg-subtle"><img src={version.previewUrl} alt={asset.name} className="size-full object-contain transition duration-300 group-hover:scale-[1.025]"/></div><div className="px-4 pt-2 pb-4"><div className="mb-3 flex items-center justify-between"><h3 className="truncate text-sm font-medium">{asset.name}</h3><span className="ml-2 shrink-0 text-xs text-muted">v{version.number}</span></div><div className="flex items-center justify-between"><Status status={version.decision}/><span className="flex items-center gap-1.5 text-[10px] text-muted"><MessageCircle className="size-3"/>{comments.filter(c => c.versionId === version.id && !c.parentId).length}</span></div></div></button>;
}
function EmptyState({ title, description, action }: { title: string; description: string; action?: React.ReactNode }) { return <div className="mx-auto flex max-w-sm flex-col items-center px-3 py-16 text-center"><span className="mb-5 flex size-14 items-center justify-center rounded-2xl border border-line bg-surface"><FolderClosed className="size-6 text-accent/70"/></span><h2 className="text-lg font-medium tracking-tight">{title}</h2><p className="mt-2 text-xs leading-relaxed text-muted">{description}</p>{action && <div className="mt-6">{action}</div>}</div>; }

function ProjectModal({ project, onClose, onSave, onArchive }: { project?: Project; onClose: () => void; onSave: (values: { name: string; client: string; description: string; color: string; dueDate: string | null }) => Promise<void>; onArchive?: () => Promise<void> }) {
  const [busy, setBusy] = useState(false); const toast = useToast();
  return <Modal title={project ? "A few little details" : "Make room for a good idea."} subtitle={project ? "Keep your project feeling like you." : "Every great project starts with a little space."} onClose={onClose}>
    <form onSubmit={async e => { e.preventDefault(); const form = new FormData(e.currentTarget); setBusy(true); try { await onSave({ name: String(form.get("name")).trim(), client: String(form.get("client")).trim(), description: String(form.get("description")).trim(), color: String(form.get("color")), dueDate: form.get("dueDate") ? String(form.get("dueDate")) : null }); } catch (error) { toast((error as Error).message, true); } finally { setBusy(false); } }}>
      <Field label="Project name"><input autoFocus name="name" required minLength={2} maxLength={120} defaultValue={project?.name} placeholder="Something worth making" className={inputClass}/></Field><Field label="Client or brand"><input name="client" maxLength={100} defaultValue={project?.client} placeholder="Who are we creating for?" className={inputClass}/></Field><Field label="A little about the project"><textarea name="description" rows={3} maxLength={1000} defaultValue={project?.description} placeholder="The idea, the direction, the bigger picture…" className={`${inputClass} resize-none`}/></Field><div className="grid grid-cols-[1fr_90px] gap-4"><Field label="Due date"><input type="date" name="dueDate" defaultValue={project?.dueDate?.slice(0, 10)} className={inputClass}/></Field><Field label="Color"><input type="color" name="color" defaultValue={project?.color ?? "#b8c6aa"} className={`${inputClass} h-11 cursor-pointer p-1.5`}/></Field></div><div className="mt-6 flex items-center justify-between gap-3">{onArchive ? <Button type="button" variant="ghost" loading={busy} onClick={async () => { setBusy(true); try { await onArchive(); } catch (e) { toast((e as Error).message, true); } finally { setBusy(false); } }}><Archive className="size-3.5"/>{project?.archived ? "Restore" : "Archive"}</Button> : <Button type="button" variant="ghost" onClick={onClose}>Maybe later</Button>}<Button type="submit" loading={busy}>{project ? "Save changes" : "Create project"}<ArrowRight className="size-3.5"/></Button></div>
    </form>
  </Modal>;
}

function UploadModal({ demo, newVersion, onClose, onUpload }: { demo: boolean; newVersion: boolean; onClose: () => void; onUpload: (file: File, onProgress: (n: number) => void, signal: AbortSignal) => Promise<void> }) {
  const [file, setFile] = useState<File | null>(null); const [dragging, setDragging] = useState(false); const [progress, setProgress] = useState<number | null>(null); const [error, setError] = useState(""); const controller = useRef<AbortController | null>(null);
  function choose(f?: File) { setError(""); if (!f) return; if (!["image/png", "image/jpeg", "image/webp"].includes(f.type)) { setError("Choose a PNG, JPG, or WebP image."); return; } if (f.size > 20 * 1024 * 1024 || !f.size) { setError("Choose an image between 1 byte and 20 MB."); return; } setFile(f); }
  useEffect(() => () => controller.current?.abort(), []);
  return <Modal title={newVersion ? "A fresh take." : "Let’s see what you’ve made."} subtitle={newVersion ? "A new version, with every previous conversation kept in place." : "Add your design and bring a little perspective to the project."} onClose={() => { controller.current?.abort(); onClose(); }}>
    <label className={`flex min-h-55 cursor-pointer flex-col items-center justify-center rounded-xl border border-dashed px-5 py-8 text-center transition ${dragging ? "border-accent bg-accent-soft" : "border-line bg-paper hover:border-accent/50"}`} onDragOver={e => { e.preventDefault(); setDragging(true); }} onDragLeave={() => setDragging(false)} onDrop={e => { e.preventDefault(); setDragging(false); if (progress === null) choose(e.dataTransfer.files[0]); }}><input type="file" aria-label="Choose a design to upload" accept="image/png,image/jpeg,image/webp" disabled={progress !== null} onChange={e => choose(e.target.files?.[0])} className="sr-only"/><span className="mb-4 flex size-12 items-center justify-center rounded-xl bg-surface shadow-sm">{file ? <FileImage className="size-5 text-accent"/> : <Upload className="size-5 text-muted"/>}</span><span className="max-w-full truncate text-sm font-medium">{file ? file.name : "Drop your design here"}</span><span className="mt-2 text-xs text-muted">{file ? `${formatBytes(file.size)} · Click to choose another file` : "or click to find it on your computer"}</span><span className="mt-5 text-[10px] text-muted">PNG, JPG, WebP · Up to 20 MB</span></label>
    {demo && <p className="mt-4 rounded-lg bg-accent-soft px-3 py-2.5 text-[11px] leading-relaxed text-accent">Demo uploads stay in this tab. Create an account to save your designs and share them with clients.</p>}
    {progress !== null && <div className="mt-5"><div className="mb-2 flex items-center justify-between text-xs text-muted"><span>{progress < 95 ? "Uploading your design…" : "Preparing your review…"}</span><span>{progress}%</span></div><div className="h-1.5 overflow-hidden rounded-full bg-subtle"><div style={{ width: `${progress}%` }} className="h-full rounded-full bg-accent transition-all"/></div></div>}
    {error && <p role="alert" className="mt-4 text-xs leading-relaxed text-red-600">{error}</p>}
    <div className="mt-6 flex justify-between gap-3"><Button variant="ghost" onClick={() => { controller.current?.abort(); if (progress !== null) { setProgress(null); } else onClose(); }}>{progress !== null ? "Cancel upload" : "Maybe later"}</Button><Button disabled={!file} loading={progress !== null} onClick={async () => { if (!file) return; const abort = new AbortController(); controller.current = abort; setError(""); setProgress(0); try { await onUpload(file, setProgress, abort.signal); } catch (e) { setError((e as Error).message); setProgress(null); } }}>{newVersion ? "Upload new version" : "Upload design"}<ArrowRight className="size-3.5"/></Button></div>
  </Modal>;
}

type ReviewLink = { id: string; expiresAt: string; allowComments: boolean; revoked: boolean };
function ShareModal({ project, demo, canEdit, onClose }: { project: Project; demo: boolean; canEdit: boolean; onClose: () => void }) {
  const [url, setUrl] = useState(""); const [days, setDays] = useState("7"); const [comments, setComments] = useState(true); const [links, setLinks] = useState<ReviewLink[]>([]); const [busy, setBusy] = useState(false); const toast = useToast();
  useEffect(() => { if (!demo && canEdit) api<ReviewLink[]>(`/projects/${project.id}/review-links`).then(setLinks).catch(e => toast(e.message, true)); }, [project.id, demo, canEdit, toast]);
  return <Modal title="A fresh pair of eyes." subtitle={`Invite someone to review ${project.client || project.name}.`} onClose={onClose}>
    <div className="mb-5 flex items-center gap-3 rounded-xl border border-line bg-paper p-3.5"><span className="flex size-10 items-center justify-center rounded-xl bg-accent-soft text-accent"><Link2 className="size-4"/></span><div><p className="text-sm font-medium">One link. Everyone on the same page.</p><p className="mt-1 text-[11px] leading-relaxed text-muted">Reviewers can view files and leave named feedback without an account.</p></div></div>
    {demo && <p className="mb-4 text-xs leading-relaxed text-muted">Demo links open the sample project. Sign in to share your own files with expiring, revocable links.</p>}
    {!canEdit && <p className="text-sm text-muted">Ask a workspace editor to create a review link.</p>}
    {canEdit && <><div className="mb-4 flex items-center justify-between"><label className="text-xs text-muted" htmlFor="share-expiry">Link expires in</label><Select id="share-expiry" value={days} onChange={e => setDays(e.target.value)}><option value="1">1 day</option><option value="7">7 days</option><option value="30">30 days</option></Select></div><label className="mb-5 flex items-center gap-2 text-xs"><input type="checkbox" checked={comments} onChange={e => setComments(e.target.checked)} className="accent-[#e66746]"/>Allow named feedback from reviewers</label><Button className="w-full" loading={busy} onClick={async () => { setBusy(true); try { if (demo) setUrl(`${location.origin}/demo?project=${encodeURIComponent(project.id)}`); else { const result = await api<{ url: string }>(`/projects/${project.id}/review-links`, { method: "POST", body: JSON.stringify({ expiresInDays: Number(days), allowComments: comments }) }); setUrl(result.url); setLinks(await api<ReviewLink[]>(`/projects/${project.id}/review-links`)); } } catch (e) { toast((e as Error).message, true); } finally { setBusy(false); } }}><Link2 className="size-3.5"/>Create review link</Button></>}
    {url && <div className="mt-4"><label className="mb-2 block text-[11px] text-muted">Copy this link now. It is only shown once.</label><div className="flex gap-2"><input aria-label="Review link" readOnly value={url} className={`${inputClass} min-w-0 text-xs`}/><Button variant="secondary" onClick={async () => { try { await navigator.clipboard.writeText(url); toast("Review link copied."); } catch { toast("Select and copy the link above."); } }}><Copy className="size-3.5"/></Button></div></div>}
    {!!links.length && <div className="mt-6 border-t border-line pt-4"><h3 className="mb-3 text-xs font-medium">Previous links</h3><div className="max-h-36 space-y-2 overflow-auto">{links.map(link => <div key={link.id} className="flex items-center justify-between gap-3 text-[11px]"><span className="text-muted">{link.revoked ? "Revoked" : new Date(link.expiresAt) < new Date() ? "Expired" : `Expires ${readableDate(link.expiresAt)}`} · {link.allowComments ? "Feedback" : "View only"}</span>{!link.revoked && <button className="text-accent" onClick={async () => { try { await api(`/review-links/${link.id}`, { method: "DELETE" }); setLinks(l => l.map(r => r.id === link.id ? { ...r, revoked: true } : r)); setUrl(""); toast("Review link revoked."); } catch (e) { toast((e as Error).message, true); } }}>Revoke</button>}</div>)}</div></div>}
  </Modal>;
}

function SettingsPanel({ data, demo, usedBytes, onUpdate, onReset }: { data: WorkspaceData; demo: boolean; usedBytes: number; onUpdate: (name: string) => void; onReset: () => void }) {
  const [busy, setBusy] = useState(false); const [invite, setInvite] = useState(""); const [role, setRole] = useState("editor"); const toast = useToast();
  const owner = data.workspace.role === "owner";
  return <div className="max-w-3xl animate-enter"><Eyebrow>A SPACE THAT FEELS LIKE YOU</Eyebrow><h1 className="mt-2 text-3xl font-medium tracking-[-.045em]">The little details.</h1><p className="mt-3 text-sm text-muted">Your workspace, your people, your way of working.</p><div className="mt-8 space-y-5"><section className="rounded-2xl border border-line bg-surface p-6"><h2 className="mb-5 text-sm font-semibold">Workspace</h2>{data.workspaces?.length > 1 && <div className="mb-5"><label className="mb-2 block text-xs text-muted" htmlFor="workspace-switch">Switch workspace</label><Select id="workspace-switch" value={data.workspace.id} onChange={async e => { try { await api("/workspace/switch", { method: "POST", body: JSON.stringify({ workspaceId: e.target.value }) }); window.location.reload(); } catch (error) { toast((error as Error).message, true); } }}>{data.workspaces.map(w => <option key={w.id} value={w.id}>{w.name} · {w.role}</option>)}</Select></div>}<form onSubmit={async e => { e.preventDefault(); const form = new FormData(e.currentTarget); const name = String(form.get("name")).trim(); setBusy(true); try { if (!demo) await api("/workspace", { method: "PATCH", body: JSON.stringify({ name }) }); onUpdate(name); toast("Workspace details updated."); } catch (e) { toast((e as Error).message, true); } finally { setBusy(false); } }}><Field label="Workspace name"><input name="name" required minLength={2} maxLength={80} defaultValue={data.workspace.name} disabled={!owner} className={inputClass}/></Field><div className="flex items-center justify-between"><p className="text-xs text-muted">Your role: {data.workspace.role}</p>{owner && <Button loading={busy}>Save changes</Button>}</div></form></section><section className="rounded-2xl border border-line bg-surface p-6"><h2 className="mb-2 text-sm font-semibold">Good company.</h2><p className="mb-5 text-xs text-muted">The people bringing a little perspective to your work.</p><div className="space-y-4">{data.members.map((m, i) => <div key={m.id} className="flex items-center gap-3"><Avatar name={m.name} color={i}/><div className="min-w-0 flex-1"><p className="truncate text-xs font-medium">{m.name}{m.id === data.user.id ? " (you)" : ""}</p><p className="mt-1 truncate text-[10px] text-muted">{m.email}</p></div><span className="rounded-md bg-subtle px-2 py-1 text-[10px] text-muted capitalize">{m.role}</span></div>)}</div>{owner && <div className="mt-6 border-t border-line pt-5"><div className="flex flex-wrap items-center gap-3"><Select aria-label="New team member role" value={role} onChange={e => setRole(e.target.value)}><option value="editor">Editor · upload and manage</option><option value="viewer">Viewer · view and comment</option></Select><Button variant="secondary" loading={busy} onClick={async () => { if (demo) { toast("Create an account to invite your team."); return; } setBusy(true); try { const result = await api<{ url: string }>("/invites", { method: "POST", body: JSON.stringify({ role }) }); setInvite(result.url); } catch (e) { toast((e as Error).message, true); } finally { setBusy(false); } }}><Users className="size-3.5"/>Create invitation</Button></div>{invite && <div className="mt-4"><p className="mb-2 text-[11px] text-muted">Single use · expires in 7 days. Share with a trusted teammate.</p><div className="flex gap-2"><input aria-label="Team invitation link" readOnly value={invite} className={`${inputClass} text-xs`}/><Button variant="secondary" onClick={async () => { try { await navigator.clipboard.writeText(invite); toast("Invitation copied."); } catch { toast("Select and copy the invitation link."); } }}><Copy className="size-3.5"/></Button></div></div>}</div>}</section><section className="flex items-center gap-4 rounded-2xl border border-line bg-surface p-6"><span className="flex size-11 items-center justify-center rounded-xl bg-subtle"><HardDrive className="size-5 text-muted"/></span><div className="flex-1"><h2 className="text-sm font-semibold">A home for your work.</h2><p className="mt-1.5 text-xs leading-relaxed text-muted">{formatBytes(usedBytes)} across {data.assets.reduce((n, a) => n + a.versions.length, 0)} versions.{demo ? " Sample files are included in this demo." : " Your files are stored privately in Amazon S3."}</p></div></section>{demo && <section className="flex flex-wrap items-center justify-between gap-4 rounded-2xl border border-line bg-surface p-6"><div><h2 className="text-sm font-semibold">A clean slate?</h2><p className="mt-1 text-xs text-muted">Reset this demo to its original projects and feedback.</p></div><Button variant="secondary" onClick={onReset}>Reset demo</Button></section>}</div></div>;
}
